def median(numbers: List[float]) -> float:
    """ For a given list of numbers, calculate the median.
    This is the middle value when the list of numbers is sorted.
    If the list has an even number of elements, return the average of
    the two middle values.
    """
    numbers.sort()
    if len(numbers) % 2 == 0:
        med = (numbers[(len(numbers)//2)-1] + numbers[len(numbers)//2])/2
    else:
        med = numbers[(len(numbers)//2)]
    return med


def mode(numbers: List[float]) -> float:
    """ For a given list of numbers, calculate the mode.
    This is the value that occurs most frequently.
    If there are multiple modes, return the smallest.
    """
    numbers.sort()
    dic = {}
    for i in numbers:
        dic[i] = dic.get(i, 0) + 1
    min = 1
    for j in dic:
        if dic[j] > min:
            min = dic[j]
            mode = j

