def is_close(numbers: List[float], threshold: float) -> bool:
    """ Return True if all numbers in given list are within threshold.
    >>> is_close([0.0, 1.0, 2.0, 3.0, 4.0], 0.25)
    True
    >>> is_close([0.0, 1.0, 1.2, 3.0, 4.0], 0.25)
    False
    """
    for number in numbers:
        if abs(number - sum(numbers) / len(numbers)) >= threshold:
            return False
    return True

    numbers_sorted = sorted(numbers)
    size = len(numbers_sorted)
    for i in range(size):
        for j in range(i, size):
            if abs(numbers_sorted[i] - numbers_sorted[j]) <= threshold:
                return True
    return False


