def parse_nested_parens_2(paren_string: str) -> int:
    """ Similar to the above function, the only difference is that this does not return an array, but an integer, which is the
    maximum nesting depth.

    >>> parse_nested_parens_2('(()()) ((())) () ((())()())')
    3
    """
    depth = 0
    max_depth = 0
    for char in paren_string:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
        max_depth = max(max_depth, depth)

    return max_depth

