def merge(xs: List[int], ys: List[int]) -> List[int]:
    """ Merge two sorted lists into one sorted list.
    >>> merge([1, 3, 4, 5], [1, 2, 4, 6])
    [1, 1, 2, 3, 4, 4, 5, 6]
    """
    if len(xs) == 0:
        return ys
    elif len(ys) == 0:
        return xs
    else:
        # Compare the first element in each array to determine which one to add first.
        # This is assuming the arrays are already sorted
        if xs[0] < ys[0]:
            return [xs[0]] + merge(xs[1:], ys)
        else:
            return [ys[0]] + merge(xs, ys[1:])

